import sys
from html.parser import HTMLParser

class P(HTMLParser):
    def __init__(self): super().__init__(); self.in_algo=False; self.in_h2=False; self.in_a=False; self.href=''; self.buf=[]; self.items=[]
    def handle_starttag(self,t,a):
        d=dict(a)
        if t=='li' and 'b_algo' in d.get('class','').split(): self.in_algo=True; self.buf=[]
        if self.in_algo and t=='h2': self.in_h2=True
        if self.in_algo and t=='a' and self.in_h2: self.in_a=True; self.href=d.get('href','')
    def handle_data(self,d):
        if self.in_algo and (self.in_h2 or not self.in_a): self.buf.append(d.strip())
    def handle_endtag(self,t):
        if self.in_algo and t=='a' and self.in_a: self.in_a=False
        if self.in_algo and t=='h2': self.in_h2=False
        if t=='li' and self.in_algo:
            text=' '.join(x for x in self.buf if x)
            if text: self.items.append((text,self.href))
            self.in_algo=False

p=P(); p.feed(open(sys.argv[1],encoding='utf-8',errors='ignore').read())
for text,href in p.items[:10]: print(text+'\\t'+href)
PY
rm -f \""'$search_file"'

